function radio(id,label,options,required=true,help=''){return `<fieldset class="question-card"><legend>${esc(label)}${required?'<span class="required-mark"> *</span>':''}</legend>${help?`<p class="question-help">${esc(help)}</p>`:''}<div class="standard-options">${options.map(o=>{let v=Array.isArray(o)?o[0]:o,t=Array.isArray(o)?o[1]:o;return `<label class="choice ${val(id)===v?'choice-selected':''}"><input type="radio" data-id="${esc(id)}" value="${esc(v)}" ${val(id)===v?'checked':''}><span>${esc(t)}</span></label>`}).join('')}</div></fieldset>`}
function checks(items,instruction='يمكن اختيار أكثر من جواب.'){return `<fieldset class="question-card"><legend>${instruction}</legend><div class="standard-options">${items.map(([id,t])=>`<label class="choice ${val(id)?'choice-selected':''}"><input type="checkbox" data-check="${id}" ${val(id)?'checked':''}><span>${esc(t)}</span></label>`).join('')}</div></fieldset>`}
function table(groups){return `<div class="instruction-card"><strong>يرجى تحديد درجة موافقتكم على العبارات التالية:</strong><div class="legend-grid">${SCALE.map(([n,t])=>`<span>${n} — ${esc(t)}</span>`).join('')}</div></div>${groups.map(([title,rows])=>`<section class="group-card"><div class="group-heading"><h3>${esc(title)}</h3></div><div class="likert-wrap"><table class="likert-table"><thead><tr><th>العبارة</th>${SCALE.map(([n,t])=>`<th title="${esc(t)}">${esc(t)}</th>`).join('')}</tr></thead><tbody>${rows.map(([id,label])=>`<tr><td>${esc(label)}</td>${SCALE.map(([n,t])=>`<td><label aria-label="${esc(t)}"><input type="radio" data-id="${id}" value="${n}" ${val(id)===n?'checked':''}></label></td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`).join('')}`}
function filters(){let h=radio('q1','س1. هل سبق لكم أن سمعتم ببرنامج الدعم المباشر للسكن؟',['نعم','لا']); if(val('q1')==='لا') return h+`<div class="instruction-card compact"><strong>شكرًا لمشاركتكم.</strong><p>ينتهي الاستبيان هنا.</p></div>`; if(val('q1')==='نعم'){h+=`<fieldset class="question-card"><legend>البريد الإلكتروني الشخصي <span class="required-mark"> *</span></legend><p class="question-help">يُستخدم لضبط مشاركة واحدة لكل مستجيب. لن يظهر للعموم.</p><input class="text-input" type="email" id="email-personal" value="${esc(val('email_personal'))}" placeholder="name@example.com"></fieldset>`; h+=radio('q2','س2. هل سبق لكم الاطلاع على معلومات حول برنامج الدعم المباشر للسكن عبر إحدى وسائل التواصل الرسمية للوزارة؟',['نعم','لا']); if(val('q2')==='نعم'){h+=`<div class="group-card"><h3>من خلال أي من وسائل التواصل الرسمية التالية اطلعتم على معلومات حول البرنامج؟</h3>${checks(officialSources)}</div>`;h+=radio('status','ما هو وضعكم الحالي بالنسبة إلى برنامج الدعم المباشر للسكن؟',statuses);} else if(val('q2')==='لا'){h+=`<div class="group-card"><h3>من خلال أي من المصادر التالية اطلعتم على معلومات حول البرنامج؟</h3>${checks(externalSources)}</div><div class="instruction-card compact"><strong>بعد تسجيل هذه الإجابة، ينتهي الاستبيان دون تقييم التواصل الرسمي للوزارة.</strong></div>`;} } return h;}
function interaction(){let h=`<div class="instruction-card"><p>يرجى الإجابة استنادًا إلى ما تعرفونه أو عايشتموه بشأن القنوات الرسمية التي تتيح للمواطنين التواصل أو التفاعل حول البرنامج، مثل خدمة «اتصل بنا» على منصة «دعم سكن»، وخدمة التواصل عبر الموقع الإلكتروني الرسمي للوزارة، والهاتف، والبريد الإلكتروني، والصفحات أو الحسابات الرسمية للوزارة على شبكات التواصل الاجتماعي عبر الرسائل أو التعليقات.</p></div>${table(G.interComm)}${table(G.interPart)}<section class="group-card"><div class="group-heading"><h3>ثالثًا: تجربة التواصل الفعلي مع الوزارة</h3></div>${radio('contact_reel','هل سبق لكم استخدام إحدى القنوات الرسمية للتواصل أو التفاعل بشأن البرنامج، لطرح سؤال أو طلب توضيح أو تقديم ملاحظة أو مقترح أو شكاية؟',['نعم','لا'])}`; if(val('contact_reel')==='نعم'){h+=radio('canal_dernier_contact','من خلال أي قناة تم آخر تواصل لكم بشأن البرنامج؟',contactChannels);h+=radio('reponse_recue','هل توصلتم برد بشأن هذا التواصل؟',['نعم','لا']);if(val('reponse_recue')==='نعم')h+=`<p class="question-help">يرجى تقييم الرد الذي توصلتم به:</p>${table(G.response)}`;} return h+'</section>';}
function understanding(){return `<div class="instruction-card"><strong>فهم البرنامج</strong><p>يرجى اختيار جواب واحد لكل سؤال. لن تُعرض الإجابات الصحيحة أثناء الاستبيان.</p></div>${quiz.map(([id,q,opts])=>radio(id,q,opts)).join('')}`}
function evaluation(){let h=`<div class="instruction-card"><p>يرجى الإجابة استنادًا إلى ما تعرفونه أو عايشتموه بشأن شروط وإجراءات الاستفادة من البرنامج.</p></div>${table(G.ease)}${table(G.accept)}`; if(beneficiary())h+=table(G.satisfaction); h+=table(G.generalImpact)+table(G.success);return h;}
const demographics={age:['من 18 إلى 24 سنة','من 25 إلى 34 سنة','من 35 إلى 44 سنة','من 45 إلى 54 سنة','55 سنة فأكثر'],gender:['ذكر','أنثى'],education:['بدون تعليم نظامي','التعليم الابتدائي','التعليم الإعدادي','التعليم الثانوي','التعليم العالي'],housing:['أملك السكن الذي أقيم فيه','أكتري السكن الذي أقيم فيه','أقيم مع الأسرة','أقيم في سكن وظيفي أو مؤقت','وضع سكني آخر'],residence:['داخل المغرب','خارج المغرب'],region:['طنجة - تطوان - الحسيمة','الشرق','فاس - مكناس','الرباط - سلا - القنيطرة','الدار البيضاء - سطات','بني ملال - خنيفرة','مراكش - آسفي','درعة - تافيلالت','سوس - ماسة','كلميم - واد نون','العيون - الساقية الحمراء','الداخلة - وادي الذهب'],professional:['موظف أو موظفة في القطاع العام','مستخدم أو مستخدمة في القطاع الخاص','مقاول أو مقاولة','متقاعد أو متقاعدة','طالب أو طالبة','بدون عمل']};
function demo(){let h=`<div class="instruction-card compact"><strong>المعلومات العامة</strong><p>تساعد هذه المعلومات في التحليل العلمي للنتائج، ولا تُستعمل للتعرف على هوية المشارك.</p></div>${radio('age','1. ما هي فئتكم العمرية؟',demographics.age)}${radio('gender','2. ما هو جنسكم؟',demographics.gender)}${radio('education','3. ما هو أعلى مستوى دراسي حصلتم عليه؟',demographics.education)}${radio('housing','4. ما هو وضعكم السكني الحالي؟',demographics.housing)}${radio('residence','5. أين تقيمون حاليًا؟',demographics.residence)}`; if(val('residence')==='داخل المغرب')h+=`<fieldset class="question-card"><legend>5-أ. جهة الإقامة داخل المغرب <span class="required-mark"> *</span></legend><select class="text-input" id="region-select"><option value="">اختاروا الجهة</option>${demographics.region.map(x=>`<option ${val('region')===x?'selected':''}>${esc(x)}</option>`).join('')}</select></fieldset>`;if(val('residence')==='خارج المغرب')h+=`<fieldset class="question-card"><legend>5-ب. بلد الإقامة خارج المغرب <span class="required-mark"> *</span></legend><input class="text-input" id="country-input" value="${esc(val('country'))}" placeholder="اكتبوا اسم البلد"></fieldset>`;h+=radio('professional','6. ما هو وضعكم المهني الحالي؟',demographics.professional);return h;}
function section(){switch(state.step){case'filters':return filters();case'information':return table(G.information);case'interaction':return interaction();case'understanding':return understanding();case'trust':return table(G.trust);case'legitimacy':return table(G.legitimacy);case'evaluation':return evaluation();case'impact':return table(G.personalImpact);case'suggestions':return `<fieldset class="question-card"><legend>ما أهم التغييرات أو الإجراءات التي تقترحونها لتحسين التواصل والتفاعل بين الوزارة والمواطنين بشأن برنامج الدعم المباشر للسكن؟</legend><textarea id="suggestion" rows="7" placeholder="اكتبوا مقترحاتكم هنا…">${esc(val('suggestion'))}</textarea></fieldset>`;case'demographics':return demo();}}
function requiredIds(step){if(step==='filters'){if(val('q1')==='لا')return['q1'];let ids=['q1','email_personal','q2'];if(val('q2')==='نعم')ids.push('status');if(val('q2')==='لا')return ids;return ids;} if(step==='information')return G.information.flatMap(g=>g[1].map(r=>r[0]));if(step==='interaction'){let ids=[...G.interComm,...G.interPart].flatMap(g=>g[1].map(r=>r[0]));ids.push('contact_reel');if(val('contact_reel')==='نعم'){ids.push('canal_dernier_contact','reponse_recue');if(val('reponse_recue')==='نعم')ids.push(...G.response[0][1].map(r=>r[0]));}return ids;}if(step==='understanding')return quiz.map(q=>q[0]);if(step==='trust')return G.trust[0][1].map(r=>r[0]);if(step==='legitimacy')return G.legitimacy[0][1].map(r=>r[0]);if(step==='evaluation'){let ids=[...G.ease,...G.accept,...G.generalImpact,...G.success].flatMap(g=>g[1].map(r=>r[0]));if(beneficiary())ids.push(...G.satisfaction[0][1].map(r=>r[0]));return ids;}if(step==='impact')return G.personalImpact[0][1].map(r=>r[0]);if(step==='demographics'){let ids=['age','gender','education','housing','residence','professional'];if(val('residence')==='داخل المغرب')ids.push('region');if(val('residence')==='خارج المغرب')ids.push('country');return ids;}return[];}
function valid(){if(state.step==='filters'&&val('q2')==='نعم'&&!officialSources.some(([id])=>val(id))){state.error='يرجى اختيار وسيلة رسمية واحدة على الأقل.';return false;}if(state.step==='filters'&&val('q2')==='لا'&&!externalSources.some(([id])=>val(id))){state.error='يرجى اختيار مصدر واحد على الأقل.';return false;}for(const id of requiredIds(state.step)){if(!val(id)){state.error='يرجى الإجابة عن جميع الأسئلة المطلوبة قبل المتابعة.';return false;}}if(state.step==='filters'&&val('email_personal')){let e=val('email_personal').trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)){state.error='يرجى إدخال بريد إلكتروني صحيح.';return false;}}state.error='';return true;}
function mean(ids){let nums=ids.map(id=>Number(val(id))).filter(Number.isFinite);return nums.length===ids.length?nums.reduce((a,b)=>a+b,0)/nums.length:null;}
function scores(){return{communication_possibility:mean(G.interComm[0][1].map(r=>r[0])),participation_possibility:mean(G.interPart[0][1].map(r=>r[0])),trust:mean(G.trust[0][1].map(r=>r[0])),legitimacy:mean(G.legitimacy[0][1].map(r=>r[0])),ease:mean(G.ease[0][1].map(r=>r[0])),satisfaction:beneficiary()?mean(G.satisfaction[0][1].map(r=>r[0])):null,general_impact:mean(G.generalImpact[0][1].map(r=>r[0])),personal_impact:beneficiary()?mean(G.personalImpact[0][1].map(r=>r[0])):null,understanding:quiz.reduce((s,[id,,,correct])=>s+(val(id)===correct?1:0),0)};}
async function emailHash(email){let bytes=new TextEncoder().encode(email.trim().toLowerCase());let digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');}
function backendStatus(s){return{'استفدت من البرنامج':'استفدت من البرنامج','قدمت طلبًا وما زال قيد المعالجة':'تقدمت بطلب، وما يزال طلبي قيد المعالجة','قدمت طلبًا ولم تتم الموافقة عليه':'تقدمت بطلب، ولم تتم الموافقة عليه','اطلعت على البرنامج ولم أتقدم بطلب للاستفادة منه':'اطلعت على البرنامج، لكنني لم أتقدم بطلب للاستفادة منه'}[s]||s;}
async function submit(){if(!valid())return render();state.sending=true;render();let normalized=val('email_personal').trim().toLowerCase(),hash=normalized?await emailHash(normalized):null;if(hash&&localStorage.getItem('housingSurveyEmailHash')===hash){state.sending=false;state.error='سبق تسجيل مشاركة بهذا البريد الإلكتروني على هذا الجهاز.';return render();}const payload={schema_version:'2026-08-07-final',submitted_at:new Date().toISOString(),answers:{...state.a,email_personal:normalized||null},scores:scores(),structural_missing:{satisfaction:beneficiary()?false:true,personal_impact:beneficiary()?false:true,response_quality:val('contact_reel')==='نعم'&&val('reponse_recue')==='نعم'?false:true}};let packed='[STRUCTURED_DATA_V2]\n'+JSON.stringify(payload)+'\n\n[OPEN_SUGGESTION]\n'+(val('suggestion')||'');let form=document.createElement('form');form.method='POST';form.action=FORM_ACTION;form.target='google-form-response';form.style.display='none';let add=(id,v)=>{if(v===undefined||v===null||v==='')return;let i=document.createElement('input');i.name='entry.'+id;i.value=v;form.appendChild(i)};add(ENTRY.q1,val('q1'));add(ENTRY.q2,val('q2'));add(ENTRY.status,backendStatus(val('status')));add(ENTRY.suggestion,packed);['age','gender','education','housing','residence','region','country','professional'].forEach(k=>add(ENTRY[k],val(k)));document.body.appendChild(form);form.submit();if(hash)localStorage.setItem('housingSurveyEmailHash',hash);setTimeout(()=>{state.done=true;state.sending=false;render();},1000);}
function nav(){let ss=steps(),i=ss.indexOf(state.step);if(state.step==='filters'&&val('q1')==='لا')return'';if(state.step==='filters'&&val('q2')==='لا')return`<nav class="form-actions"><span></span><button class="primary-button" id="submit-end" type="button">إرسال الإجابة وإنهاء الاستبيان</button></nav>`;return `<nav class="form-actions">${i>0?'<button class="secondary-button" id="prev" type="button">السابق</button>':'<span></span>'}${i<ss.length-1?'<button class="primary-button" id="next" type="button">التالي</button>':`<button class="primary-button submit-button" id="submit" type="button" ${state.sending?'disabled':''}>${state.sending?'جارٍ إرسال الإجابات…':'إرسال الإجابات'}</button>`}</nav>`;}
function render(){if(state.done){$('#root').innerHTML=`<main class="site-shell" dir="rtl"><section class="success-card"><div class="success-icon">✓</div><p class="eyebrow">نهاية الاستبيان</p><h1>شكرًا جزيلًا على مشاركتكم</h1><p>تم تسجيل إجاباتكم. ستظل جميع المعطيات سرية، ولن تُستعمل إلا لأغراض البحث العلمي.</p></section></main>`;return;}let ss=steps(),i=Math.max(ss.indexOf(state.step),0),pct=(i+1)/ss.length*100;$('#root').innerHTML=`<main class="site-shell" dir="rtl"><header class="hero"><div class="hero-accent"></div><p class="eyebrow">بحث أكاديمي بسلك الدكتوراه</p><h1>استبيان حول التواصل العمومي المرتبط ببرنامج الدعم المباشر للسكن</h1><p class="hero-lead">يهدف هذا البحث إلى التعرف على تصورات المواطنين بشأن التواصل العمومي المرتبط بالبرنامج، وعلى تقييمهم لمختلف جوانبه.</p><div class="privacy-note"><span>◉</span><p>جميع الأجوبة سرية، ولن تُستعمل إلا لأغراض البحث العلمي.</p></div><button class="intro-toggle" id="intro-toggle" type="button">${state.intro?'إخفاء مقدمة الاستبيان':'عرض مقدمة الاستبيان'} <span>${state.intro?'−':'+'}</span></button>${state.intro?`<div class="intro-copy"><p>في إطار إعداد بحث أكاديمي بسلك الدكتوراه، أضع بين أيديكم هذا الاستبيان، الذي يندرج ضمن دراسة حول التواصل العمومي المرتبط ببرنامج الدعم المباشر للسكن.</p><p>وتكتسي مشاركتكم أهمية كبيرة، لما ستوفره من معطيات أساسية تسهم في إغناء هذا البحث وتعزيز نتائجه من الناحية العلمية. لذلك، نرجو منكم الإجابة عن الأسئلة بكل موضوعية ودقة.</p><p>وتفضلوا بقبول فائق الشكر والتقدير على تعاونكم.</p><details><summary>توضيحات</summary><div class="definition-list"><p><strong>الوزارة:</strong> وزارة إعداد التراب الوطني والتعمير والإسكان وسياسة المدينة.</p><p><strong>وسائل التواصل الرسمية للوزارة:</strong> مجموع القنوات والوسائط التي تعتمدها الوزارة بصفة رسمية للإعلام والتواصل بشأن برنامج الدعم المباشر للسكن ونشر المعلومات المتعلقة بأهدافه وشروط الاستفادة منه ومساطره ومستجداته، ومنها الموقع الإلكتروني الرسمي للوزارة، ومنصة «دعم سكن» وتطبيقها، والصفحات والحسابات الرسمية على شبكات التواصل الاجتماعي.</p><p><strong>وسائل التواصل الرسمية التي تتيح التفاعل:</strong> القنوات الرسمية التي تمكّن المواطنين من توجيه الاستفسارات وطلب التوضيحات وتقديم الملاحظات أو المقترحات أو الشكايات بشأن البرنامج، عبر خدمات الاتصال في منصة «دعم سكن» والموقع الرسمي، والهاتف، والبريد الإلكتروني، والرسائل أو التعليقات عبر الحسابات الرسمية للوزارة.</p></div></details></div>`:''}</header><section class="progress-panel"><div class="progress-copy"><span>المرحلة ${i+1}</span><strong>${esc(stepTitles[state.step])}</strong><span dir="ltr">${i+1} / ${ss.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div></section><section id="questionnaire-form" class="form-section"><div class="section-heading"><p>الاستبيان</p><h2>${esc(stepTitles[state.step])}</h2></div>${state.error?`<div class="error-message" role="alert">${esc(state.error)}</div>`:''}${section()}${nav()}</section><iframe name="google-form-response" class="submission-frame" title="إرسال الاستبيان"></iframe><footer><p>شكرًا لتعاونكم ومساهمتكم في هذا البحث العلمي.</p></footer></main>`;bind();}
function bind(){document.querySelectorAll('input[type=radio][data-id]').forEach(x=>x.onchange=()=>{let id=x.dataset.id;set(id,x.value);if(id==='q1'&&x.value!=='نعم')del('email_personal','q2','status',...officialSources.map(z=>z[0]),...externalSources.map(z=>z[0]));if(id==='q2'){if(x.value==='نعم')del(...externalSources.map(z=>z[0]));else del(...officialSources.map(z=>z[0]),'status');}if(id==='status'&&x.value!=='استفدت من البرنامج')del(...G.satisfaction[0][1].map(r=>r[0]),...G.personalImpact[0][1].map(r=>r[0]));if(id==='contact_reel'&&x.value==='لا')del('canal_dernier_contact','reponse_recue',...G.response[0][1].map(r=>r[0]));if(id==='reponse_recue'&&x.value==='لا')del(...G.response[0][1].map(r=>r[0]));if(id==='residence'){if(x.value==='داخل المغرب')del('country');else del('region');}render();});document.querySelectorAll('input[type=checkbox][data-check]').forEach(x=>x.onchange=()=>{set(x.dataset.check,x.checked?'1':'');render();});let e=$('#email-personal');if(e)e.oninput=()=>set('email_personal',e.value);let s=$('#suggestion');if(s)s.oninput=()=>set('suggestion',s.value);let r=$('#region-select');if(r)r.onchange=()=>{set('region',r.value);render();};let c=$('#country-input');if(c)c.oninput=()=>set('country',c.value);let it=$('#intro-toggle');if(it)it.onclick=()=>{state.intro=!state.intro;render();};let n=$('#next');if(n)n.onclick=()=>{if(!valid())return render();let ss=steps(),i=ss.indexOf(state.step);state.step=ss[i+1];state.error='';render();scrollToForm();};let p=$('#prev');if(p)p.onclick=()=>{let ss=steps(),i=ss.indexOf(state.step);state.step=ss[i-1];state.error='';render();scrollToForm();};let sub=$('#submit');if(sub)sub.onclick=submit;let se=$('#submit-end');if(se)se.onclick=submit;}
function scrollToForm(){requestAnimationFrame(()=>$('#questionnaire-form')?.scrollIntoView({behavior:'smooth',block:'start'}));}
const style=document.createElement('style');style.textContent=`.likert-wrap{overflow-x:auto}.likert-table{width:100%;border-collapse:collapse;min-width:760px;background:#fff}.likert-table th,.likert-table td{border:1px solid rgba(15,23,42,.12);padding:.85rem;text-align:center}.likert-table th:first-child,.likert-table td:first-child{text-align:right;min-width:360px}.likert-table input{width:20px;height:20px}.likert-table thead th{font-weight:800;background:rgba(15,23,42,.04)}.likert-table thead th:not(:first-child){font-size:15px;font-weight:700;line-height:1.4;white-space:normal;min-width:90px}.legend-grid{grid-template-columns:repeat(5,minmax(0,1fr))}.group-card+.instruction-card{margin-top:1rem}.question-card input[type=email]{width:100%}@media(max-width:700px){.likert-table{min-width:660px}.likert-table th:first-child,.likert-table td:first-child{min-width:300px}.likert-table thead th:not(:first-child){font-size:13px;min-width:76px}.legend-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}`;document.head.appendChild(style);
render();